type UseMutateResult<Data, Err, Args extends any[]> = {
  isPending: boolean;
  error: Err | undefined;
  data: Data | undefined;
  mutate: (...args: Args) => void;
  mutateAsync: (...args: Args) => Promise<Data>;
  reset: () => void;
}

examples.code:
function CreateButton() {
  const { mutate, isPending, error, data }: UseMutateResult<Todo, Error, [string]> = 
    useMutate(createTodo);

  return (
    <div>
      <button onClick={() => mutate('New')} disabled={isPending}>
        {isPending ? 'Creating...' : 'Create'}
      </button>
      {error && <p className="error">{error.message}</p>}
      {data && <p>Created: {data.id}</p>}
    </div>
  );
}

function MutationExample() {
  const { mutate, mutateAsync, reset } = useMutate(updateTodo);

  // Fire and forget - errors stored in state
  const handleClick = () => {
    mutate('123', { completed: true });
  };

  // Await result - errors thrown
  const handleSubmit = async () => {
    try {
      const result = await mutateAsync('123', { completed: true });
      // Navigate or perform next action
      router.push(`/todos/${result.id}`);
    } catch (err) {
      // Handle error
    }
  };

  // Reset for showing form again
  const handleReset = () => {
    reset();
  };
}
